<template><div class="grid gap-1.5"><label :for="id" class="text-sm font-semibold text-adm-ink">{{ label }}<span v-if="required" class="text-adm-danger-ink"> *</span></label><slot/><p v-if="hint" :id="hintId" class="text-xs text-adm-ink-muted">{{ hint }}</p><p v-if="error" :id="errorId" class="text-sm text-adm-danger-ink" role="alert">{{ error }}</p></div></template>
<script setup lang="ts">import { computed } from 'vue';const props=defineProps<{id:string;label:string;hint?:string;error?:string;required?:boolean}>();const hintId=computed(()=>props.id+'-hint');const errorId=computed(()=>props.id+'-error')</script>
